from rich.console import Console
from rich.prompt import Prompt, InvalidResponse
import io

def test_markup_disabled():
    # Use a StringIO to capture output
    console = Console(file=io.StringIO(), markup=False)

    class MyPrompt(Prompt):
        def process_response(self, value):
            raise InvalidResponse("[red]Invalid![/red]")

    error = InvalidResponse("[red]Invalid![/red]")
    prompt = MyPrompt("Enter something", console=console)
    prompt.on_validate_error("some value", error)

    output = console.file.getvalue()
    print(f"Output: {repr(output)}")
    if "[red]Invalid![/red]" in output:
        print("Markup was NOT rendered (as expected with markup=False)")
    else:
        print("Markup was rendered")

if __name__ == "__main__":
    test_markup_disabled()

from rich.console import Console
from rich.prompt import Prompt, InvalidResponse
import io

def test_markup_disabled():
    # Use a StringIO to capture output, and force_terminal=True to see ANSI codes
    console = Console(file=io.StringIO(), markup=False, force_terminal=True)

    class MyPrompt(Prompt):
        def process_response(self, value):
            raise InvalidResponse("[red]Invalid![/red]")

    error = InvalidResponse("[red]Invalid![/red]")
    prompt = MyPrompt("Enter something", console=console)
    prompt.on_validate_error("some value", error)

    output = console.file.getvalue()
    print(f"Output: {repr(output)}")
    if "[red]Invalid![/red]" in output:
        print("Markup was NOT rendered (as expected with markup=False)")
    elif "Invalid!" in output and any(c == '\x1b' for c in output):
        print("Markup was rendered (with ANSI codes)")
    elif "Invalid!" in output:
        print("Markup was rendered (without ANSI codes)")
    else:
        print("Something else happened")

if __name__ == "__main__":
    test_markup_disabled()
